-- 2. 工具（10 件，覆盖 4 个类别、各状态/损坏程度/审核状态）
INSERT INTO `tool` (`id`, `tool_code`, `name`, `model_spec`, `category`, `damage_level`, `deposit`, `storage_location`, `usage_instruction`, `images`, `purchase_date`, `supplier_info`, `status`, `audit_status`, `audit_opinion`, `create_by`, `create_time`, `update_time`) VALUES
(1, 'SQ-G-WX-0001', '手电钻', '博世 GSB550（功率 550W，夹头最大直径 13mm，转速 0-3000 转/分钟）', 1, 2, 200.00, '社区服务站 2 号工具柜',
 '1.操作前检查电源线是否破损，夹头是否夹紧钻头；2.钻孔时垂直对准目标位置，缓慢按下开关，避免用力过猛；3.禁止用于石材等坚硬材质；4.使用后关闭开关，拔掉电源，清理钻头碎屑。',
 JSON_ARRAY('https://github.com/cd-water.png', 'https://github.com/cd-water.png'), '2024-03-15', '鼎力机电设备有限公司，139****8901', 1, 2, NULL, 2, '2026-08-15 09:25:00', '2026-09-12 17:40:00'),
(2, 'SQ-G-WX-0002', '电动螺丝刀', '绿巨力充电式（3.6V，批头 6 支装，扭矩 5N·m）', 1, 2, 150.00, '社区服务站 2 号工具柜',
 '1.使用前确认电池电量充足，选择合适批头；2.拧螺丝时保持垂直，听到咔哒声即已拧紧，避免过力；3.不使用时关闭电源并收纳批头。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2024-05-20', '鼎力机电设备有限公司，139****8901', 2, 2, NULL, 2, '2026-08-15 09:40:00', '2026-10-16 09:10:00'),
(3, 'SQ-G-WX-0003', '电动扳手', '得力 EDL-580（最大扭力 350N·m，方头 1/2 英寸）', 1, 4, 150.00, '社区服务站 2 号工具柜',
 '1.根据螺母规格选择合适套筒并锁紧；2.握持平稳后启动，防止反扭矩伤手；3.达到扭矩后立即松开开关；4.使用后检查套筒并归还。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2023-11-08', '鼎力机电设备有限公司，139****8901', 3, 2, NULL, 2, '2026-08-15 09:50:00', '2026-10-04 14:20:00'),
(4, 'SQ-G-YY-0001', '修枝剪', '张小泉园林剪（碳钢，全长 210mm）', 2, 3, 50.00, '社区服务站 3 号工具柜',
 '1.修剪前确认刀口锋利无缺口；2.粗枝请用剪口根部发力，避免剪切超过 20mm 的枝条；3.使用后擦拭并上油防锈。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2023-04-12', '绿洲园艺用品商行，137****2210', 1, 2, NULL, 2, '2026-08-15 10:00:00', '2026-09-22 18:10:00'),
(5, 'SQ-G-YY-0002', '割草机', '本田 UMK450（四冲程汽油，幅宽 450mm）', 2, 2, 300.00, '社区服务站 3 号工具柜',
 '1.使用前检查汽油机油液位，远离火源加油；2.启动后保持双手握持，匀速推进；3.清理草坪上的石块铁丝后再作业；4.使用后待机器冷却再归还。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2022-09-01', '绿洲园艺用品商行，137****2210', 1, 2, NULL, 2, '2026-08-15 10:10:00', '2026-08-26 09:50:00'),
(6, 'SQ-G-YY-0003', '园艺浇水喷壶', '乐扣 3L 气压式（可调节雾化/水柱）', 2, 1, 20.00, '社区服务站 3 号工具柜',
 '1.加水不超过壶体 max 刻度线；2.打气后按压手柄出水，雾化/水柱可旋转调节；3.使用后倒净余水晾干。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2026-10-10', '绿洲园艺用品商行，137****2210', 1, 3, '请补充喷壶口径规格照片后重新提交审核', 2, '2026-10-16 15:00:00', '2026-10-16 16:20:00'),
(7, 'SQ-G-QJ-0001', '高压洗车水枪', '凯驰 K2（压力 110bar，流量 360L/h）', 3, 2, 100.00, '社区服务站 1 号工具柜',
 '1.接好水管后先开水源再开机；2.严禁对人、动物和电器喷射；3.高压束与被喷物体保持 30cm 以上距离；4.使用后先关机再断水，盘好水管。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2023-06-18', '洁邻清洁设备部，136****7755', 1, 2, NULL, 2, '2026-08-15 10:20:00', '2026-10-13 10:05:00'),
(8, 'SQ-G-QJ-0002', '家用吸尘器', '小米无线 K10（吸力 120AW，续航 60 分钟）', 3, 3, 120.00, '社区服务站 1 号工具柜',
 '1.使用前确认电量充足，按需更换吸头；2.严禁吸取水、大颗粒硬物和燃烧物；3.使用后清理尘盒并归位充电。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2022-12-05', '洁邻清洁设备部，136****7755', 1, 2, NULL, 2, '2026-08-15 10:30:00', '2026-10-14 08:05:00'),
(9, 'SQ-G-QT-0001', '家用折叠梯', '稳固达四步铝梯（承重 150kg）', 4, 2, 80.00, '社区服务站 1 号工具柜',
 '1.展开后确认四脚平稳、卡扣锁死；2.站立时不超过最高踏板；3.单侧承重请勿超过 75kg；4.折叠收纳后归还。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2024-01-10', '家居帮手杂货铺，135****3321', 1, 1, NULL, 2, '2026-10-17 10:00:00', '2026-10-17 10:00:00'),
(10, 'SQ-G-QT-0002', '手推车', '金鸿平板车（载重 300kg，可折叠扶手）', 4, 4, 100.00, '社区服务站 1 号工具柜',
 '1.装载物品不超过栏板高度，重物置于底部；2.推行时注意速度与转弯半径；3.使用后清空并折叠停放。',
 JSON_ARRAY('https://github.com/cd-water.png'), '2021-07-22', '家居帮手杂货铺，135****3321', 4, 2, NULL, 2, '2026-08-15 10:40:00', '2026-09-01 14:00:00');

